// payment/gateway.ts
/** 決済サービスが処理を始める前に断ったことが、仕様で確かな失敗か */
export function wasNotProcessed(e: PaymentUnavailableError): boolean {
  return e.status === 429; // 決済サービスの仕様で確かめた値だけを足す
}

// orders/orderService.ts の catch
if (e instanceof PaymentDeclinedError ||
    (e instanceof PaymentUnavailableError && wasNotProcessed(e))) {
  order.status = 'PAYMENT_FAILED';
  ...
}
// handlers/checkout.ts も wasNotProcessed(e) で retryable を決める
